(function(root){
const users=[{id:'author-a',name:'Demo Rule Author',role:'Author'},{id:'approver-b',name:'Demo Approver',role:'Approver'},{id:'auditor-c',name:'Demo Auditor',role:'Auditor'},{id:'admin-d',name:'Demo Administrator',role:'Administrator'}];
const kinds=['amount','hours','dormant','reversal','period','duplicate','interbranch'];
const copy=x=>JSON.parse(JSON.stringify(x));
function can(user,action){return action==='read'||action==='sandbox'||(action==='author'&&['Author','Administrator'].includes(user.role))||(action==='review'&&['Approver','Administrator'].includes(user.role))||(action==='investigate'&&user.role!=='Auditor')}
function validate(rules){if(!Array.isArray(rules))throw Error('Rules must be a list.');let ids=new Set();for(let r of rules){if(!r.id||ids.has(r.id))throw Error('Rule IDs must be unique.');ids.add(r.id);if(!kinds.includes(r.kind)||!String(r.name).trim()||r.name.length>100||!String(r.description).trim()||r.description.length>1000||!['High','Medium'].includes(r.severity)||typeof r.enabled!=='boolean'||!Number.isFinite(r.threshold)||r.threshold<=0||r.threshold>999999999)throw Error('Invalid rule definition.');if(['hours','dormant','reversal','duplicate'].includes(r.kind)&&!Number.isInteger(r.threshold))throw Error('Hours, days and counts must be whole numbers.');if(r.kind==='hours'&&(r.threshold<9||r.threshold>24))throw Error('Closing hour must be from 9 to 24.');if(r.kind==='duplicate'&&r.threshold<2)throw Error('Duplicate count must be at least 2.');}return true}
function stamp(){return new Date().toISOString()}
function audit(state,user,event,target,details){state.audit.push({seq:state.audit.length+1,at:stamp(),actor:user.name,actorId:user.id,role:user.role,event,target,details});}
function init(rules){validate(rules);return {version:1,rules:copy(rules),requests:[],versions:[{version:1,at:stamp(),actor:'Demo baseline',reason:'Initial approved controls (existing browser settings)',rules:copy(rules)}],audit:[],next:1}}
function draft(state,user,{action,rules,reason,ruleId=''}){if(!can(user,'author'))throw Error('This role cannot create rule changes.');validate(rules);if(!reason.trim())throw Error('A business rationale is required.');if(JSON.stringify(rules)===JSON.stringify(state.rules))throw Error('This proposal does not change the approved rules.');let r={id:'CR-'+String(state.next++).padStart(3,'0'),action,ruleId,rules:copy(rules),reason:reason.trim(),creator:user.id,creatorName:user.name,base:state.version,status:'Draft',createdAt:stamp()};state.requests.push(r);audit(state,user,'Draft created',r.id,`${action}: ${reason.trim()}`);return r}
function submit(state,user,id){let r=state.requests.find(x=>x.id===id);if(!r||r.status!=='Draft'||r.creator!==user.id||!can(user,'author'))throw Error('Only the draft author can submit this change.');if(r.base!==state.version)throw Error('Approved rules changed. Create a fresh proposal from the current version.');r.status='Pending';r.submittedBy=user.id;r.submittedAt=stamp();audit(state,user,'Submitted for approval',id,r.reason);return r}
function decide(state,user,id,approve,reason){let r=state.requests.find(x=>x.id===id);if(!r||r.status!=='Pending'||!can(user,'review'))throw Error('This role cannot review this request.');if(r.creator===user.id||r.submittedBy===user.id)throw Error('The author cannot approve or reject their own request.');if(!reason.trim())throw Error('A review rationale is required.');if(approve&&r.base!==state.version)throw Error('Stale request: approved rules changed. Reject it and create a fresh proposal.');if(approve){validate(r.rules);state.rules=copy(r.rules);state.version++;state.versions.push({version:state.version,at:stamp(),actor:user.name,request:id,reason:reason.trim(),rules:copy(r.rules)});}r.status=approve?'Approved':'Rejected';r.reviewer=user.name;r.reviewReason=reason.trim();r.reviewedAt=stamp();audit(state,user,approve?'Approved and activated':'Rejected',id,reason.trim());return r}
function discard(state,user,id){let r=state.requests.find(x=>x.id===id);if(!r||r.status!=='Draft'||r.creator!==user.id||!can(user,'author'))throw Error('Only the author can discard this draft.');r.status='Discarded';audit(state,user,'Draft discarded',id,r.reason)}
root.Governance={users,can,validate,init,draft,submit,decide,discard,audit};
if(typeof module!=='undefined')module.exports=root.Governance;
})(globalThis);
